public class MessageTemplateFactory(string resourceName = null, Action<Humidifier.Wisdom.MessageTemplate> factoryAction = null) : ResourceFactory<Humidifier.Wisdom.MessageTemplate>(resourceName)
{

    internal InnerMessageTemplateContentFactory ContentFactory { get; set; }

    internal InnerMessageTemplateGroupingConfigurationFactory GroupingConfigurationFactory { get; set; }

    internal InnerMessageTemplateMessageTemplateAttributesFactory DefaultAttributesFactory { get; set; }

    protected override Humidifier.Wisdom.MessageTemplate Create()
    {
        var messageTemplateResult = CreateMessageTemplate();
        factoryAction?.Invoke(messageTemplateResult);

        return messageTemplateResult;
    }

    private Humidifier.Wisdom.MessageTemplate CreateMessageTemplate()
    {
        var messageTemplateResult = new Humidifier.Wisdom.MessageTemplate
        {
            GivenName = InputResourceName,
        };

        return messageTemplateResult;
    }
    public override void CreateChildren(Humidifier.Wisdom.MessageTemplate result)
    {
        base.CreateChildren(result);

        result.Content ??= ContentFactory?.Build();
        result.GroupingConfiguration ??= GroupingConfigurationFactory?.Build();
        result.DefaultAttributes ??= DefaultAttributesFactory?.Build();
    }

} // End Of Class

